/*
 * A287019  Primes that can be generated by the concatenation in base 2, in
 *          descending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287019
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 31, u32 n <= 35, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   ensure_capacity, floor_log2_uint64, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A287019: the nth prime that equals
   concat_bin(i+1 , i) for i ≥ 0,
   where concat_bin(a,b) = a << len(b) | b
   and len(b) is the binary length of b
   (len(0) is defined to be 1).  */

#include <stdbool.h>
#include <stddef.h>
#include "../utils/ensure_capacity.h"
#include "../utils/floor_log2_uint64.h"
#include "../utils/is_prime_big.h"

seq_t a(idx_t n) {
    /* static cache for already computed primes */
    static seq_t *cache = NULL;
    static size_t cache_cap = 0;
    static idx_t cached = 0;     /* number of primes stored */
    static idx_t next_i = 0;     /* next i (starting from 0) to process */

    /* offset 1: a(1) is the first term */
    if (n == 0) return 0; /* undefined for the sequence, but safe */

    if (cached < n) {
        /* reserve space for n primes */
        ensure_capacity(n, &cache_cap, (void **)&cache, sizeof(seq_t));

        while (cached < n) {
            idx_t i = next_i++;
            idx_t len = (i == 0) ? 1 : (floor_log2_uint64(i) + 1);
            seq_t shifted = ((seq_t)(i + 1) << (unsigned)len);
            seq_t val     = shifted | (seq_t)i;
            if (is_prime_big(val)) {
                cache[cached++] = val;
            }
        }
    }
    return cache[n - 1];
}
